    # Chỉ mục gộp cho truy vấn thật: "nhật ký của NGƯỜI này, mới nhất trước".
    op.create_index('ix_audit_logs_user_recent', 'audit_logs',
                    ['user_id', sa.literal_column('created_at DESC')], unique=False)

    # Thêm cột theo BA BƯỚC. Thêm thẳng NOT NULL mà không có mặc định thì Postgres từ
