    # Điền theo ĐÚNG gói mà mỗi người đang dùng.
    op.execute("""
        UPDATE subscriptions SET mailbox_scope_days = CASE tier
            WHEN 'pro' THEN 180
            WHEN 'max' THEN 365
            ELSE 90
        END
    """)

    # batch_alter_table: SQLite không có ALTER COLUMN, Alembic sẽ dựng lại bảng.
    # Postgres thì chạy ALTER bình thường. Dùng cách này để bản di trú chạy được
    # trên CẢ HAI — test dựng lại schema từ database trống dùng SQLite.
